  "cop.cardHealth": "ಆರೋಗ್ಯ ಅಂಕ",
  "cop.cardHealthSub": "ಸಂಯೋಜಿತ ಆರ್ಥಿಕ ಆರೋಗ್ಯ",
  "cop.whatHeading": "ಕೋಪೈಲಟ್ ಏನು ಮಾಡುತ್ತದೆ",
  "cop.whatDesc": "ನಿಮ್ಮ ಕಾರ್ಯಸ್ಥಳದ ಪ್ರತಿ ಸಂಖ್ಯೆಯನ್ನೂ ಓದಿರುವ ಹಣಕಾಸು ವಿಶ್ಲೇಷಕ ಎಂದು ಭಾವಿಸಿ. ಇದು ಸಾರಾಂಶಿಸುತ್ತದೆ, ಶ್ರೇಣಿಗೊಳಿಸುತ್ತದೆ ಮತ್ತು ಉತ್ತರಿಸುತ್ತದೆ - ನಂತರ ನಿಜವಾದ ಕೆಲಸ ಮಾಡುವ ಪುಟಕ್ಕೆ ನಿಮ್ಮನ್ನು ಒಪ್ಪಿಸುತ್ತದೆ.",
  "cop.featBriefDesc": "ನಗದು, ರನ್‌ವೇ, ಬಾಕಿ ಮತ್ತು ಇಂದು ಏನು ಬಾಕಿ ಇದೆ ಎಂಬುದರ ಒಂದು-ಪರದೆಯ ಸಾರಾಂಶ.",
  "cop.featActionsDesc": "ನಗದು ಪ್ರಭಾವದಿಂದ ಶ್ರೇಣಿಗೊಳಿಸಿದ ಹ್ಯೂರಿಸ್ಟಿಕ್ ಮುಂದಿನ-ಅತ್ಯುತ್ತಮ-ಹಂತಗಳು, ಪ್ರತಿಯೊಂದೂ ಸರಿಯಾದ ಸಾಧನಕ್ಕೆ ಆಳವಾಗಿ-ಜೋಡಿಸುತ್ತದೆ.",
  "cop.featLauncherDesc": "ನೀವು ಬಯಸಿದ್ದನ್ನು ಟೈಪ್ ಮಾಡಿ ('ಬಾಕಿ ಬೆನ್ನಟ್ಟಿ', 'ಮುನ್ಸೂಚನೆ') ಮತ್ತು ನೇರವಾಗಿ ಅಲ್ಲಿಗೆ ಹೋಗಿ.",
  "cop.featQaDesc": "'ನಗದು ಏಕೆ ಕಡಿಮೆಯಾಗಿದೆ?' ಎಂಬುದಕ್ಕೆ ಕೇವಲ ನಿಮ್ಮ ಮೆಟ್ರಿಕ್‌ಗಳ ಆಧಾರದ ಸರಳ-ಭಾಷೆಯ ಉತ್ತರಗಳು.",
  "cop.featGoalDesc": "ರನ್‌ವೇ ಗುರಿಯನ್ನು ಹೊಂದಿಸಿ; ಯೋಜಕ ಸಂಗ್ರಹ / ಕಡಿತ / ಸಾಲದ ಮಿಶ್ರಣವನ್ನು ಸೂಚಿಸುತ್ತದೆ.",
  "cop.featAttentionDesc": "ನಿಮ್ಮ ಡೇಟಾದಿಂದ ಹೊರಬಂದ ಅಸಂಗತಿಗಳು ಮತ್ತು ಅಪಾಯಗಳು, ಇತ್ತೀಚಿನವು ಮೊದಲು.",
  "cop.jumpHeading": "ಸಂಬಂಧಿತ ಮಾಡ್ಯೂಲ್‌ಗೆ ಹೋಗಿ",
  "cop.autoComputed": "ಸ್ವಯಂ-ಲೆಕ್ಕಿತ",
  "cop.briefDesc": "ಇಂದು ಮುಖ್ಯವಾದ ಸಂಖ್ಯೆಗಳ ಸರಳ-ಭಾಷೆಯ ಸಾರಾಂಶ. ನಿಮ್ಮ ಡೇಟಾ ಬದಲಾದಂತೆ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ರಿಫ್ರೆಶ್ ಆಗುತ್ತದೆ.",
  "cop.openFullBrief": "ಪೂರ್ಣ CFO ಸಾರಾಂಶ ತೆರೆಯಿರಿ",
  "cop.briefCopied": "ಸಾರಾಂಶ ಕ್ಲಿಪ್‌ಬೋರ್ಡ್‌ಗೆ ನಕಲಿಸಲಾಗಿದೆ",
  "cop.copyBrief": "ಸಾರಾಂಶ ನಕಲಿಸಿ",
  "cop.actionsDesc": "ತುರ್ತು ಮತ್ತು ನಗದು ಪ್ರಭಾವದಿಂದ ಶ್ರೇಣಿಗೊಳಿಸಿದ ಹ್ಯೂರಿಸ್ಟಿಕ್ ಮುಂದಿನ-ಅತ್ಯುತ್ತಮ-ಹಂತಗಳು. ಒಂದರ ಮೇಲೆ ಕ್ರಮ ಕೈಗೊಂಡರೆ ಅದನ್ನು ನಿಜವಾಗಿ ಮಾಡುವ ಪುಟ ತೆರೆಯುತ್ತದೆ - ಕೋಪೈಲಟ್ ಎಂದಿಗೂ ತಾನಾಗಿಯೇ ಕಾರ್ಯಗತಗೊಳಿಸುವುದಿಲ್ಲ.",
  "cop.potentialImpact": "ಸಂಭಾವ್ಯ ನಗದು ಪ್ರಭಾವ:",
  "cop.restore": "ಪುನಃಸ್ಥಾಪಿಸಿ",
  "cop.markHandled": "ನಿಭಾಯಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸಿ",
  "cop.launcherDesc": "ನೀವು ಏನು ಮಾಡಬಯಸುತ್ತೀರೋ ಅದನ್ನು ಸರಳ ಪದಗಳಲ್ಲಿ ಟೈಪ್ ಮಾಡಿ - ಲಾಂಚರ್ ಕೀವರ್ಡ್‌ಗಳನ್ನು ಹೊಂದಿಸಿ ನಿಮ್ಮನ್ನು ನೇರವಾಗಿ ಸರಿಯಾದ ಮಾಡ್ಯೂಲ್‌ಗೆ ಕರೆದೊಯ್ಯುತ್ತದೆ. ಇದು ಕೇವಲ ನ್ಯಾವಿಗೇಟ್ ಮಾಡುತ್ತದೆ; ಕಾರ್ಯವನ್ನು ನಿಮಗಾಗಿ ನಿರ್ವಹಿಸುವುದಿಲ್ಲ.",
  "cop.launcherPlaceholder": "ಉದಾ. ಬಾಕಿ ಬೆನ್ನಟ್ಟಿ, ವಾಟ್-ಇಫ್ ಚಲಾಯಿಸಿ, GST ಸಲ್ಲಿಸಿ…",
  "cop.launcherNoMatch": "ಹೊಂದಾಣಿಕೆಯ ಕ್ರಮವಿಲ್ಲ. “ಸಂಗ್ರಹ”, “ಮುನ್ಸೂಚನೆ”, “ಖರ್ಚು” ಅಥವಾ “ತೆರಿಗೆ” ನಂತಹ ಪದಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ.",
  "cop.qaDescLead": "ಸರಳ ಭಾಷೆಯಲ್ಲಿ ಏನನ್ನಾದರೂ ಕೇಳಿ. AI ತರ್ಕಿಸುತ್ತದೆ",
  "cop.qaDescBold": "ಕೇವಲ ನಿಮ್ಮ ಲೈವ್ ಆರ್ಥಿಕ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್",
  "cop.qaDescRest": "- ನಗದು, ರನ್‌ವೇ, ಸ್ವೀಕರಿಸಬೇಕಾದವು, ಸಾಲ ಮತ್ತು ಆರೋಗ್ಯದ ಮೇಲೆ. AI ಲಭ್ಯವಿಲ್ಲದಿದ್ದರೆ, ಅದೇ ಸಂಖ್ಯೆಗಳಿಂದ ತ್ವರಿತ ಆಫ್‌ಲೈನ್ ಉತ್ತರ ಸಿಗುತ್ತದೆ.",
  "cop.qaPlaceholder": "ನಿಮ್ಮ ಹಣಕಾಸಿನ ಬಗ್ಗೆ ಕೇಳಿ…",
