  "cop.offlineNote": "ಆಫ್‌ಲೈನ್ ಉತ್ತರ - AI ಇಲ್ಲದೆ ನಿಮ್ಮ ಮೆಟ್ರಿಕ್‌ಗಳಿಂದ ಲೆಕ್ಕಹಾಕಲಾಗಿದೆ.",
  "cop.aiNotConfigured": "AI ಕಾನ್ಫಿಗರ್ ಆಗಿಲ್ಲ - ಆಫ್‌ಲೈನ್ ಉತ್ತರ ಬಳಸಲಾಗುತ್ತಿದೆ",
