  "cop.goalDesc": "ರನ್‌ವೇ ಗುರಿಯನ್ನು ಹೊಂದಿಸಿ, ಅಂತರವನ್ನು ಮುಚ್ಚಲು ಯೋಜಕ ಸಂಗ್ರಹ, ಕಡಿತ ಮತ್ತು ಸಾಲದ ಹ್ಯೂರಿಸ್ಟಿಕ್ ಮಿಶ್ರಣವನ್ನು ಸೂಚಿಸುತ್ತದೆ. ಇದು ಕ್ರಮ ಕೈಗೊಳ್ಳಲು ಒಂದು ಸಲಹೆ - ಯಾವುದಕ್ಕೂ ಸೂಚನೆಯಲ್ಲ.",
