  "cop.collectHeading": "ಮೊದಲು-ಸಂಗ್ರಹಿಸಿ ಕೆಲಸಪಟ್ಟಿ",
  "cop.collectDesc": "ಸಂಗ್ರಹ ಆದ್ಯತೆಯಿಂದ ಶ್ರೇಣಿಗೊಳಿಸಿದ ನಿಮ್ಮ ತೆರೆದ ಇನ್‌ವಾಯ್ಸ್‌ಗಳು - ದೊಡ್ಡ ಬ್ಯಾಲೆನ್ಸ್‌ಗಳು ಮತ್ತು ಅತಿ ಹೆಚ್ಚು-ಬಾಕಿ ಇರುವವು ಮೇಲಕ್ಕೆ ಏರುತ್ತವೆ, ಆದ್ದರಿಂದ ಒಂದು ಬೆಳಗಿನ ಬೆನ್ನಟ್ಟುವಿಕೆ ಅತಿ ಹೆಚ್ಚು ನಗದನ್ನು ಮರಳಿ ಪಡೆಯುತ್ತದೆ. ನೀವು ಕೆಲಸ ಮಾಡುತ್ತಾ ಟಿಕ್ ಮಾಡಿ; ಕೋಪೈಲಟ್ ನಿಮಗಾಗಿ ಎಂದಿಗೂ ಯಾರನ್ನೂ ಸಂಪರ್ಕಿಸುವುದಿಲ್ಲ.",
  "cop.stillToChase": "ಇನ್ನೂ ಬೆನ್ನಟ್ಟಬೇಕಾದದ್ದು:",
  "cop.collectEmptyTitle": "ಬೆನ್ನಟ್ಟಲು ಯಾವುದೇ ತೆರೆದ ಇನ್‌ವಾಯ್ಸ್‌ಗಳಿಲ್ಲ",
  "cop.collectEmptyBody": "ಎಲ್ಲವೂ ಪಾವತಿಯಾಗಿದೆ - ಸಂಗ್ರಹಗಳು ಸ್ವಚ್ಛವಾಗಿವೆ.",
  "cop.openCollections": "ಸಂಗ್ರಹಗಳನ್ನು ತೆರೆಯಿರಿ",
  "cop.invoiceNowDesc": "ನಿಮ್ಮ ಇನ್‌ವಾಯ್ಸ್ ಪಟ್ಟಿಯ ವಿರುದ್ಧ ಹೊಂದಿಸಿದ ವಿತರಿಸಿದ ಮತ್ತು ರವಾನಿಸಿದ ಆದೇಶಗಳು - ಪೂರೈಸಲಾಗಿದೆ ಆದರೆ ಬಿಲ್ ಆಗಿಲ್ಲ ಎಂದು ತೋರುವ ಯಾವುದೇ ವಸ್ತು ಎತ್ತಲು ಕಾಯುತ್ತಿರುವ ಆದಾಯ. ಇದು ಅಂತರವನ್ನು ಸೂಚಿಸುತ್ತದೆ; ನೀವು ಸ್ವೀಕರಿಸಬೇಕಾದವುಗಳಲ್ಲಿ ಇನ್‌ವಾಯ್ಸ್ ಎತ್ತುತ್ತೀರಿ.",
  "cop.likelyUnbilled": "ಬಹುಶಃ ಬಿಲ್ ಆಗಿಲ್ಲ:",
  "cop.invoiceNowEmptyTitle": "ಇನ್‌ವಾಯ್ಸ್ ಬಾಕಿ ಇರುವ ಯಾವುದೇ ಪೂರೈಸಿದ ಆದೇಶಗಳಿಲ್ಲ",
  "cop.invoiceNowEmptyBody": "ಒಂದೋ ಇನ್ನೂ ಏನೂ ವಿತರಿಸಿಲ್ಲ ಅಥವಾ ಎಲ್ಲವೂ ಬಿಲ್ ಆಗಿರುವಂತೆ ತೋರುತ್ತದೆ.",
  "cop.raiseInvoices": "ಸ್ವೀಕರಿಸಬೇಕಾದವುಗಳಲ್ಲಿ ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ಎತ್ತಿ",
  "cop.vendorTimingDesc": "ಮುಂಬರುವ ಬಾಧ್ಯತೆಗಳನ್ನು {days} ದಿನಗಳೊಳಗೆ ನಿಜವಾಗಿ ಪಾವತಿಸಬೇಕಾದವು - ಶಾಸನಬದ್ಧ ಬಾಕಿಗಳು, ವೇತನದಾರಿ, ಸಾಲಗಳು ಮತ್ತು ಬಾಕಿ ಇರುವ ಯಾವುದೇ ವಸ್ತು - ಮತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ಕಾಯಬಹುದಾದವು ಎಂದು ವಿಭಜಿಸುತ್ತದೆ, ಆದ್ದರಿಂದ ನೀವು ಗಡುವನ್ನು ತಪ್ಪಿಸದೆ ನಗದನ್ನು ಹಿಡಿದಿಟ್ಟುಕೊಳ್ಳುತ್ತೀರಿ. ಕೇವಲ ಸಮಯ ಸಲಹೆ; ಇದು ಏನನ್ನೂ ಬಿಡುಗಡೆ ಮಾಡುವುದಿಲ್ಲ.",
  "cop.payNow": "ಈಗ ಪಾವತಿಸಿ",
  "cop.canWait": "ಕಾಯಬಹುದು",
  "cop.payNowExceedsCash": "ಈಗ-ಪಾವತಿಸುವ ಒಟ್ಟು ಕೈಯಲ್ಲಿರುವ ನಗದನ್ನು ಮೀರುತ್ತದೆ - ಲಭ್ಯ ನಿಧಿಗಳೊಳಗೆ ಅನುಕ್ರಮಗೊಳಿಸಲು ಪಾವತಿ ಆದ್ಯತೆಗಾರವನ್ನು ತೆರೆಯಿರಿ.",
  "cop.vendorTimingEmpty": "ಮುಂದಿನ 45 ದಿನಗಳಲ್ಲಿ ಯಾವುದೇ ಬಾಧ್ಯತೆಗಳಿಲ್ಲ",
  "cop.nothingDeferrable": "ಈ ಅವಧಿಯಲ್ಲಿ ಮುಂದೂಡಬಹುದಾದದ್ದು ಏನೂ ಇಲ್ಲ.",
  "cop.reviewPayables": "ಖರ್ಚಿನಲ್ಲಿ ಪಾವತಿಸಬೇಕಾದವನ್ನು ಪರಿಶೀಲಿಸಿ",
  "cop.focusCopied": "ಗಮನ ಪಟ್ಟಿ ನಕಲಿಸಲಾಗಿದೆ",
  "cop.thisWeekHeading": "ಈ ವಾರದ ಗಮನ",
  "cop.copyList": "ಪಟ್ಟಿ ನಕಲಿಸಿ",
  "cop.thisWeekDesc": "ಈ ವಾರ ನಿಮ್ಮ ಸಮಯಕ್ಕೆ ಅತ್ಯಂತ ಯೋಗ್ಯವಾದ ಕೆಲವು ಕ್ರಮಗಳು, ಪ್ರಭಾವದಿಂದ ಶ್ರೇಣಿಗೊಳಿಸಿ ನೇರವಾಗಿ ನಿಮ್ಮ ಸಂಖ್ಯೆಗಳಿಂದ ಓದಲಾಗಿದೆ. ನೀವು ಹೋಗುತ್ತಾ ಅವನ್ನು ಟಿಕ್ ಮಾಡಿ - ಇದು ಮಾಡಬೇಕಾದ ಪಟ್ಟಿ, ಕಾರ್ಯಗತಗೊಳಿಸುವವನಲ್ಲ.",
  "cop.remainingCount": "{total}ರಲ್ಲಿ {remaining} ಬಾಕಿ",
  "cop.kpiExplainerHeading": "ಹಳಿ-ತಪ್ಪಿದ KPI ವಿವರಕ",
  "cop.kpiExplainerDesc": "ನಿಮ್ಮ ಉಳಿಸಿದ KPI ಗುರಿಗಳನ್ನು ಲೈವ್ ಮೌಲ್ಯಗಳೊಂದಿಗೆ ಹೋಲಿಸುತ್ತದೆ, ಅತಿ ಹೆಚ್ಚು ದೂರ ಇರುವುದನ್ನು ಆರಿಸುತ್ತದೆ ಮತ್ತು ಅದು ಏಕೆ ಹಳಿ ತಪ್ಪಿದೆ ಮತ್ತು ಯಾವ ಸನ್ನೆಗಳು ಅದನ್ನು ಚಲಿಸುತ್ತವೆ ಎಂಬುದನ್ನು ಸರಳ ಪದಗಳಲ್ಲಿ ವಿವರಿಸುತ್ತದೆ. ಕೇವಲ ರೋಗನಿರ್ಣಯ - KPI ಗುರಿಗಳ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಗುರಿಗಳನ್ನು ಹೊಂದಿಸಿ; ಜೋಡಿಸಿದ ಪುಟಗಳ ಮೂಲಕ ಕ್ರಮ ಕೈಗೊಳ್ಳಿ.",
