  "voi.overviewHeading": "ಧ್ವನಿ-ಮೊದಲ ಹಣಕಾಸು, ಪ್ರಾಮಾಣಿಕವಾಗಿ ವ್ಯಾಪ್ತಿಗೊಳಿಸಲಾಗಿದೆ",
  "voi.overviewBody": "ಇಲ್ಲಿನ ಎಲ್ಲವೂ ಇಂದು ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ - ಯಾವುದೇ ಕ್ಲೌಡ್ ಸ್ಪೀಚ್ ಸೇವೆ ಅಗತ್ಯವಿಲ್ಲ. ಪ್ರತಿ ಟೂಲ್ ಆಧಾರವಾದ API ಅನ್ನು ಪತ್ತೆಹಚ್ಚುತ್ತದೆ ಮತ್ತು ಅದು ಲಭ್ಯವಿಲ್ಲದಿದ್ದಾಗ ಟೈಪಿಂಗ್‌ಗೆ ಹಿಂತಿರುಗುತ್ತದೆ.",
