  "voi.badgeFallbackOnly": "ಫಾಲ್‌ಬ್ಯಾಕ್ ಮಾತ್ರ",
  "voi.overviewFallback": "ಧ್ವನಿ ಗುಣಮಟ್ಟವು ಸಂಪೂರ್ಣವಾಗಿ ನಿಮ್ಮ ಸಾಧನ ಮತ್ತು ಬ್ರೌಸರ್ ಮೇಲೆ ಅವಲಂಬಿತ. Web Speech ಗುರುತಿಸುವಿಕೆ ಡೆಸ್ಕ್‌ಟಾಪ್‌ನಲ್ಲಿ Chrome/Edge ಮತ್ತು Android WebView ಗಳಲ್ಲಿ ಉತ್ತಮವಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ; Safari/iOS ಬೆಂಬಲ ಭಾಗಶಃ. ಉಚ್ಚಾರಣೆ ಮತ್ತು ಪ್ರಾದೇಶಿಕ ನಿಖರತೆ ಸ್ಥಾಪಿತ OS ಸ್ಪೀಚ್ ಎಂಜಿನ್‌ಗೆ ಅನುಗುಣವಾಗಿ ಬದಲಾಗುತ್ತದೆ - ಗುರುತಿಸುವಿಕೆ ಲಭ್ಯವಿಲ್ಲದಿದ್ದಾಗ, ಇಲ್ಲಿನ ಪ್ರತಿ ಟೂಲ್ ಟೈಪ್ ಮಾಡಿದ ಇನ್‌ಪುಟ್ ಸ್ವೀಕರಿಸುತ್ತದೆ.",
  "voi.captureHeading": "ಧ್ವನಿ ಟಿಪ್ಪಣಿ → ವಹಿವಾಟು ಕರಡು",
  "voi.captureFallback": "ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮೈಕ್ರೊಫೋನ್ ಡಿಕ್ಟೇಶನ್ ಲಭ್ಯವಿಲ್ಲ. ಕೆಳಗಿನ ಬಾಕ್ಸ್‌ನಲ್ಲಿ ಸಾಲನ್ನು ಟೈಪ್ ಮಾಡಿ - ಪಾರ್ಸಿಂಗ್ ನಿಖರವಾಗಿ ಅದೇ ರೀತಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ.",
