  "voi.payReminderSubtitle": "ಬಾಕಿ ಬಿಲ್ ಆಯ್ಕೆಮಾಡಿ (ಅಥವಾ ಭರ್ತಿ ಮಾಡಿ), ಸ್ವರ ಆಯ್ಕೆಮಾಡಿ, ಮತ್ತು Headroom ನೀವು ಗಟ್ಟಿಯಾಗಿ ಓದಬಹುದಾದ, ನಕಲಿಸಬಹುದಾದ ಅಥವಾ ಕರೆಯ ಮೇಲೆ ಪುನರುಚ್ಚರಿಸಬಹುದಾದ ಸಭ್ಯ ಮಾತನಾಡಿದ ಜ್ಞಾಪನೆ ರಚಿಸುತ್ತದೆ. ಏನೂ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.",
