  "voi.greetingFallback": "ಇಲ್ಲಿ ಆಡಿಯೋ ರೆಕಾರ್ಡಿಂಗ್ ಬೆಂಬಲಿತವಲ್ಲ. ನೀವು ಇನ್ನೂ ಸ್ಕ್ರಿಪ್ಟ್ ಗಟ್ಟಿಯಾಗಿ ಓದಿದ್ದನ್ನು ಆಲಿಸಬಹುದು (ಪಠ್ಯದಿಂದ ಧ್ವನಿ ಲಭ್ಯವಿದ್ದರೆ) ಮತ್ತು ನಿಮ್ಮ ಫೋನ್‌ನ ಸ್ವಂತ ರೆಕಾರ್ಡರ್‌ನಲ್ಲಿ ರೆಕಾರ್ಡ್ ಮಾಡಲು ಅದನ್ನು ನಕಲಿಸಬಹುದು.",
