  "voi.askBalanceFallback": "ಇಲ್ಲಿ ಮೈಕ್ರೊಫೋನ್ ಪ್ರಶ್ನೆಗಳು ಲಭ್ಯವಿಲ್ಲ - ನಿಮ್ಮ ಪ್ರಶ್ನೆ ಟೈಪ್ ಮಾಡಿ ಮತ್ತು ನಾವು ಕೆಳಗೆ ಉತ್ತರಿಸುತ್ತೇವೆ.",
