  "voi.workLogFallback": "ಇಲ್ಲಿ ಡಿಕ್ಟೇಶನ್ ಲಭ್ಯವಿಲ್ಲ - ಪ್ರತಿ ನಮೂದನ್ನು ಟೈಪ್ ಮಾಡಿ ಮತ್ತು ಸೇರಿಸಿ ಒತ್ತಿ; ಸಮಯ ಮುದ್ರೆಗಳನ್ನು ಇನ್ನೂ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.",
  "voi.listeningDescribe": "ಆಲಿಸುತ್ತಿದೆ… ನೀವು ಏನು ಮಾಡಿದಿರಿ ಎಂದು ವಿವರಿಸಿ.",
