  "tok.subtitle": "RBI e-rupee & GIFT-City ರೈಲ್‌ಗಳಿಗಾಗಿ ಪ್ರೋಗ್ರಾಮೆಬಲ್-ಪಾವತಿ ನಿಯಮಗಳು, ಎಸ್ಕ್ರೋಗಳು ಮತ್ತು ಟೋಕನೀಕೃತ ಆಸ್ತಿಗಳನ್ನು ಅವು ಲೈವ್ ಆಗುವ ಮೊದಲೇ ವಿನ್ಯಾಸ ಮಾಡಿ.",
  "tok.honestNote": "ಇಂದೇ ವಿನ್ಯಾಸ ಮಾಡಿ ಮತ್ತು ಸಿಮ್ಯುಲೇಟ್ ಮಾಡಿ; CBDC / ಟೋಕನೀಕರಣ ರೈಲ್‌ಗಳು ಲೈವ್ ಆದಂತೆ ಸೆಟಲ್‌ಮೆಂಟ್ ಸಕ್ರಿಯವಾಗುತ್ತದೆ. ಇಲ್ಲಿ ಎಲ್ಲವೂ ನಿಜವಾದ ಸ್ಪೆಕ್‌ಗಳು, ಸ್ಪ್ಲಿಟ್‌ಗಳು ಮತ್ತು ಬ್ಯಾಲೆನ್ಸ್‌ಗಳನ್ನು ಸ್ಥಳೀಯವಾಗಿ ಲೆಕ್ಕ ಹಾಕುತ್ತದೆ - ಯಾವುದೇ ಲೈವ್ ಬ್ಲಾಕ್‌ಚೈನ್ ಅಥವಾ e-rupee ನೆಟ್‌ವರ್ಕ್ ಕರೆಗಳಿಲ್ಲ.",
