  "tok.buildTodayHeading": "ಇಂದು ನೀವು ಏನನ್ನು ನಿರ್ಮಿಸಬಹುದು",
  "tok.buildTodayBody": "ಪ್ರೋಗ್ರಾಮೆಬಲ್ ಹಣವು ಒಂದು ರೂಪಾಯಿಗೆ ನಿಯಮಗಳನ್ನು ಹೊತ್ತೊಯ್ಯಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ: ಅದನ್ನು ಒಂದು ಉದ್ದೇಶಕ್ಕೆ ಲಾಕ್ ಮಾಡಬಹುದು, ಷರತ್ತು ಪೂರೈಸಿದಾಗ ಮಾತ್ರ ಬಿಡುಗಡೆ ಮಾಡಬಹುದು, ಅಥವಾ ಡೆಲಿವರಿ ವಿರುದ್ಧ ಅಟಾಮಿಕ್ ಆಗಿ ಸೆಟಲ್ ಮಾಡಬಹುದು. ಭಾರತದ e-rupee (RBI CBDC) ಮತ್ತು GIFT-City ಟೋಕನೀಕರಣ ರೈಲ್‌ಗಳು ಇನ್ನೂ ಬೆಳೆಯುತ್ತಿವೆ - ಆದ್ದರಿಂದ ಇಲ್ಲಿ ನೀವು ಸ್ಪೆಕ್‌ಗಳನ್ನು ಈಗ ವಿನ್ಯಾಸ ಮಾಡುತ್ತೀರಿ ಮತ್ತು ಸಿಮ್ಯುಲೇಟ್ ಮಾಡುತ್ತೀರಿ, ರೈಲ್‌ಗಳು ತೆರೆದಂತೆ ಅವು ನಿಯೋಜಿಸಬಹುದಾದವಾಗುತ್ತವೆ.",
  "tok.ovErupeeTitle": "e-Rupee (CBDC) ಲೆಡ್ಜರ್",
