  "front.whatForBody": "Headroom ರೋಡ್‌ಮ್ಯಾಪ್ ಕ್ಷಣದಲ್ಲೇ ಗ್ರಹಿಸುವ, ನಿರ್ಧರಿಸುವ ಮತ್ತು ಸೆಟಲ್ ಮಾಡುವ - ಮತ್ತು ನಾಳಿನ ಕ್ವಾಂಟಮ್ ಕಂಪ್ಯೂಟರ್‌ಗಳ ವಿರುದ್ಧ ಸುರಕ್ಷಿತವಾಗಿ ಉಳಿಯುವ ಹಣಕಾಸನ್ನು ಸೂಚಿಸುತ್ತದೆ. ಇದರಲ್ಲಿ ಕೆಲವು ಇಂದಿನ ಡೇಟಾದ ಮೇಲೆ ನಿರ್ಮಿಸಬಹುದಾಗಿದೆ ಮತ್ತು ಇಲ್ಲಿ ಕೆಲಸ ಮಾಡುವ ಟೂಲ್‌ಗಳಾಗಿ ಸಾಗಿಸಲಾಗಿದೆ. ಉಳಿದವು ಇನ್ನೂ ಬೆಳೆಯುತ್ತಿರುವ ರೈಲ್‌ಗಳ (RTP, ಪ್ರೋಗ್ರಾಮೆಬಲ್ CBDC, ಸ್ಟ್ರೀಮಿಂಗ್ ಪೇರೋಲ್) ಮೇಲೆ ಅವಲಂಬಿತವಾಗಿವೆ - ಅವು ಪ್ರಾಮಾಣಿಕ, ಸಂವಾದಾತ್ಮಕ ಪೂರ್ವವೀಕ್ಷಣೆಗಳಾಗಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ ಇದರಿಂದ ನಾವು ಲೈವ್ ಹಣ ಚಲನೆಯನ್ನು ನಕಲಿ ಮಾಡದೆ ನೀವು ವಿನ್ಯಾಸವನ್ನು ರೂಪಿಸಬಹುದು.",
