  "front.supercomputeFootnote": "ಪ್ರತಿ ರನ್ ನಿಮ್ಮ ಊಹೆಗಳ ಸುತ್ತ ಒಂದು ಸಾಮಾನ್ಯ ವಿತರಣೆಯಿಂದ ಮಾಸಿಕ ಆದಾಯ ಮತ್ತು ವೆಚ್ಚವನ್ನು ಸೆಳೆಯುತ್ತದೆ. ಹೆಚ್ಚಿನ ರನ್ ಎಣಿಕೆಗಳು ಕಂಪ್ಯೂಟ್ ಸಮಯದ ವೆಚ್ಚದಲ್ಲಿ ಸುಗಮ ಪರ್ಸೆಂಟೈಲ್‌ಗಳನ್ನು ನೀಡುತ್ತವೆ. ಸೂಚಕ ಯೋಜನಾ ಟೂಲ್, ಗ್ಯಾರಂಟಿ ಅಲ್ಲ.",
  "front.quantumHeading": "ಪೋಸ್ಟ್-ಕ್ವಾಂಟಮ್ ವಲಸೆ ಸಿದ್ಧತೆ",
  "front.quantumBlurb": "ನಿಮ್ಮ ಹಣಕಾಸು ಸ್ಟ್ಯಾಕ್‌ಅನ್ನು ಕ್ವಾಂಟಮ್ ಡಿಕ್ರಿಪ್ಷನ್ ವಿರುದ್ಧ ಸುರಕ್ಷಿತಗೊಳಿಸುವ ಹಂತಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ. ಪ್ರಗತಿಯನ್ನು ಉಳಿಸಲಾಗುತ್ತದೆ.",
