  "front.stepsComplete": "{done}/{total} ಹಂತಗಳು ಪೂರ್ಣ",
  "front.quantumFootnote": "NIST PQC ಮಾರ್ಗದರ್ಶನ (Kyber/Dilithium/SPHINCS+) ಆಧಾರಿತ. \"Harvest-now-decrypt-later\" ಎಂದರೆ ಇಂದು ಎಕ್ಸ್‌ಫಿಲ್ಟ್ರೇಟ್ ಮಾಡಿದ ಡೇಟಾವನ್ನು ಕ್ವಾಂಟಮ್ ಕಂಪ್ಯೂಟರ್‌ಗಳು ಪಕ್ವವಾದಾಗ ಡಿಕ್ರಿಪ್ಟ್ ಮಾಡಬಹುದು - ದೀರ್ಘಾವಧಿಯ ಹಣಕಾಸು ದಾಖಲೆಗಳು ಆದ್ಯತೆ.",
  "front.eventsHeading": "ಲೈವ್ ಈವೆಂಟ್ ಸ್ಟ್ರೀಮ್",
  "front.eventsBlurb": "ನಿಮ್ಮ ಸ್ಟೋರ್‌ನಾದ್ಯಂತ ಇತ್ತೀಚಿನ ಬದಲಾವಣೆಗಳು, \"event bus\" ಫೀಡ್ ಆಗಿ ರೆಂಡರ್ ಮಾಡಲಾಗಿದೆ - ಈವೆಂಟ್-ಚಾಲಿತ ಹಣಕಾಸಿನ ಪೂರ್ವವೀಕ್ಷಣೆ.",
  "front.eventsEmpty": "ಇನ್ನೂ ಯಾವುದೇ ಈವೆಂಟ್‌ಗಳಿಲ್ಲ. ವಹಿವಾಟುಗಳು ಅಥವಾ ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ಸೇರಿಸಿ ಮತ್ತು ಅವು ಇಲ್ಲಿ ಸ್ಟ್ರೀಮ್ ಆಗುತ್ತವೆ.",
  "front.radarHeading": "ಟೆಕ್-ಸಿದ್ಧತೆ ರೇಡಾರ್",
  "front.radarBlurb": "ನಿಮ್ಮ ಹಣಕಾಸು ಕಾರ್ಯಾಚರಣೆ ಇಂದು ನಾಲ್ಕು ಫ್ರಾಂಟಿಯರ್‌ಗಳಾದ್ಯಂತ ಎಲ್ಲಿ ಇದೆ ಎಂದು ರೇಟ್ ಮಾಡಿ (0 = ಪ್ರಾರಂಭವಾಗಿಲ್ಲ, 5 = ಮುಂಚೂಣಿ). ನಿಮ್ಮ ಖಾತೆಗೆ ಉಳಿಸಲಾಗಿದೆ.",
  "front.radarOverall": "ಒಟ್ಟಾರೆ ಫ್ರಾಂಟಿಯರ್ ಸಿದ್ಧತೆ",
  "front.radarFootnote": "ನಿಮ್ಮ ರೋಡ್‌ಮ್ಯಾಪ್‌ಅನ್ನು ಕೇಂದ್ರೀಕರಿಸಲು ಸ್ವಯಂ-ಮೌಲ್ಯಮಾಪನ - ಅತ್ಯಂತ ಕಡಿಮೆ ಅಕ್ಷವು ಸಾಮಾನ್ಯವಾಗಿ ಅತ್ಯುತ್ತಮ ಮುಂದಿನ ಹೂಡಿಕೆ. ಭಾರತೀಯ ರೈಲ್‌ಗಳ ಮೇಲೆ ನಿರ್ಮಿಸಬಹುದಾದಾಗ Headroom ಪ್ರತಿಯೊಂದರ ವಿರುದ್ಧ ಟೂಲ್‌ಗಳನ್ನು ಸಾಗಿಸುತ್ತದೆ.",
  "front.rtpTitle": "Request-to-Pay ವಿನ್ಯಾಸಕ",
  "front.rtpBlurb": "ವ್ಯವಹಾರಗಳಿಗಾಗಿ UPI Request-to-Pay ರೈಲ್‌ಗಳು ಪಕ್ವವಾದ ನಂತರ ವೆಂಡರ್ ಸ್ವೀಕರಿಸುವ ರಚನಾತ್ಮಕ RTP ಆಬ್ಜೆಕ್ಟ್‌ಅನ್ನು ವಿನ್ಯಾಸ ಮಾಡಿ. ಇದು ಪೂರ್ವವೀಕ್ಷಣೆ ಪೇಲೋಡ್ ನಿರ್ಮಿಸುತ್ತದೆ - ಇದು ಇನ್ನೂ ನಿಜವಾದ ಪಾವತಿ ವಿನಂತಿಯನ್ನು ಕಳುಹಿಸುವುದಿಲ್ಲ.",
  "front.rtpCompose": "ವಿನಂತಿ ರಚಿಸಿ",
  "front.rtpPayloadPreview": "RTP ಪೇಲೋಡ್ ಪೂರ್ವವೀಕ್ಷಣೆ",
  "front.streamingTitle": "ಸ್ಟ್ರೀಮಿಂಗ್-ಪೇರೋಲ್ ಸಿಮ್ಯುಲೇಟರ್",
  "front.streamingBlurb": "ಮಾಸಿಕದ ಬದಲಿಗೆ ಪ್ರತಿ ಸೆಕೆಂಡ್ ವೇತನ ಸಂಚಯನವನ್ನು ರೂಪಿಸಿ. ಕೇವಲ ವಿವರಣಾತ್ಮಕ ಗಣಿತ - ನಿಜವಾದ ನಿರಂತರ ಪಾವತಿಗೆ ಸ್ಟ್ರೀಮಿಂಗ್ ರೈಲ್‌ಗಳು ಬೇಕು ಮತ್ತು ಇದು ನಿಮ್ಮ ಪೇರೋಲ್‌ಗೆ ಜೋಡಿಸಲಾಗಿಲ್ಲ.",
  "front.treasuryTitle": "ಸ್ವಾಯತ್ತ-ಟ್ರೆಷರಿ ಪಾಲಿಸಿ",
  "front.treasuryBlurb": "ಸ್ವಯಂ-ಚಾಲಿತ ಟ್ರೆಷರಿ ಏಜೆಂಟ್ ಪಾಲಿಸುವ ಗಾರ್ಡ್‌ರೈಲ್‌ಗಳನ್ನು ವ್ಯಾಖ್ಯಾನಿಸಿ - ಕನಿಷ್ಠ ಬಫರ್, ಸ್ವೀಪ್ ಮಿತಿಗಳು, ಇಳುವರಿ ಫ್ಲೋರ್. ನಿಮ್ಮ ಉದ್ದೇಶಿತ ಪಾಲಿಸಿಯಾಗಿ ಉಳಿಸಲಾಗಿದೆ; ಸ್ವಾಯತ್ತ ಟ್ರೆಷರಿ ಸಕ್ರಿಯಗೊಳ್ಳುವವರೆಗೆ ಯಾವುದೇ ಹಣ ಚಲಿಸುವುದಿಲ್ಲ.",
  "front.m2mTitle": "ಮಶೀನ್-ಟು-ಮಶೀನ್ ಪಾವತಿ ಕಲ್ಪನೆ",
  "front.m2mBlurb": "ಪ್ರೋಗ್ರಾಮೆಬಲ್ ಹಣದ ಮೇಲೆ ಒಂದು IoT ಸಾಧನವು ಬಳಸುವ ಪ್ರತಿ ಘಟಕಕ್ಕೆ ಪಾವತಿಸುವುದನ್ನು (ಉದಾ. ಒಂದು EV ಪ್ರತಿ ಕಿಮೀಗೆ ಸೆಟಲ್ ಮಾಡುವುದು, ಮೀಟರ್ ಪ್ರತಿ kWhಗೆ) ರೂಪಿಸಿ. ಕಲ್ಪನಾತ್ಮಕ ಕ್ಯಾಲ್ಕುಲೇಟರ್ - ಯಾವುದೇ ಸಾಧನ ಅಥವಾ CBDC ರೈಲ್ ಸಂಪರ್ಕಗೊಂಡಿಲ್ಲ.",
